{
  "version": "1",
  "text": "You look wonderfully composed in this soft, sand-colored linen ensemble. The tailored blazer gives your silhouette a clean line that draws attention to the waist, while the wide-leg jumpsuit flows comfortably for all the movement of your evening at the office. The ballet flats offer the effortless ease you asked for, keeping you grounded and ready to focus on your vocal lesson without distraction.",
  "how_to_wear": [
    "Keep the blazer open to let the jumpsuit’s neckline breathe and draw eyes toward your collarbone.",
    "Wear the leather belt loosely around the waist of the jumpsuit to softly define your shape."
  ],
  "wrong_photos": [],
  "swap": {},
  "named": [
    {
      "n": "#16·24",
      "what": "a beige linen blazer with hand-sewn decorative buttons"
    },
    {
      "n": "#177·37",
      "what": "a matching beige wide-leg jumpsuit with a short-sleeve collar shirt and tie waist"
    },
    {
      "n": "#110·07",
      "what": "beige suede ballet flats with a soft slip-on silhouette"
    },
    {
      "n": "#36·42",
      "what": "a colorful woven-pattern crossbody bag with a tan leather base and strap"
    },
    {
      "n": "#284·41",
      "what": "a khaki leather belt featuring a large metallic rose buckle"
    }
  ],
  "about_items": [
    {
      "n": "#16·24",
      "text": "This lightweight beige linen blazer features a relaxed, unlined cut with notched lapels and two front flap pockets. The hand-sewn decorative buttons add an artisanal touch while maintaining effortless drape against your body."
    },
    {
      "n": "#177·37",
      "text": "The beige linen jumpsuit has a classic collar shirt top with short sleeves and a front button placket that ties at the waist. Its wide-leg silhouette flows down to cropped hems with rolled cuffs, balancing comfort and structure for all-day wear."
    },
    {
      "n": "#110·07",
      "text": "These beige suede ballet flats feature a soft slip-on design with a rounded toe and a cushioned rubber sole. Their lightweight build ensures they feel as natural to your feet as any sock."
    },
    {
      "n": "#36·42",
      "text": "This vibrant crossbody bag showcases a colorful geometric pattern in red, blue, green, and gold tones across its upper woven panel. The lower half and strap are crafted from durable tan canvas, making it both eye-catching and practical for carrying essentials during your evening."
    },
    {
      "n": "#284·41",
      "text": "This khaki leather belt features a polished metallic rose buckle that adds an elegant focal point. Its smooth texture complements the matte finish of the linen pieces without overwhelming them."
    }
  ]
}
